function StreakCard({ currentStreak }: { currentStreak: number }) {
  const animatedStreak = useAnimatedValue(currentStreak, 800);
  const flameRef = useRef<HTMLDivElement>(null);
  const prevStreakRef = useRef(currentStreak);
  const [milestoneMsg, setMilestoneMsg] = useState<string | null>(null);

  useEffect(() => {
    if (currentStreak > prevStreakRef.current && currentStreak > 0) {
      const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      let particleCount = window.innerWidth < 768 ? 10 : 20; // Mobile performance limit
      let newMsg = null;
      if (currentStreak === 7) { newMsg = "7-day streak! 🔥"; particleCount = window.innerWidth < 768 ? 15 : 35; }
      else if (currentStreak === 30) { newMsg = "30-day streak! 🏆"; particleCount = window.innerWidth < 768 ? 20 : 40; }
      else if (currentStreak === 100) { newMsg = "100-day streak! 💎"; particleCount = window.innerWidth < 768 ? 25 : 50; }
      requestAnimationFrame(() => setMilestoneMsg(newMsg));

      if (!prefersReducedMotion && flameRef.current) {
        const rect = flameRef.current.getBoundingClientRect();
        const originX = (rect.left + rect.width / 2) / window.innerWidth;
        const originY = (rect.top + rect.height / 2) / window.innerHeight;
        confetti({
          particleCount,
          spread: 60,
          origin: { x: originX, y: originY },
          colors: ['#4f46e5', '#ea580c', '#16a34a', '#ec4899'],
          disableForReducedMotion: true,
        });
      }
    }
    prevStreakRef.current = currentStreak;
  }, [currentStreak]);

  return (
    <div style={{ background: '#fff', padding: '20px', borderRadius: '12px', border: '1px solid #f1f5f9' }}>
      <div ref={flameRef} style={{ width: '36px', height: '36px', borderRadius: '10px', background: '#f0fdf4', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#16a34a' }}>🔥</div>
      <div style={{ fontSize: '28px', fontWeight: 800, margin: '12px 0 4px 0', color: '#0f172a' }}>
        {animatedStreak} days
      </div>
      <div style={{ fontSize: '12px', color: '#64748b' }}>Current Streak</div>
      <div style={{ fontSize: '11px', color: '#16a34a', fontWeight: 600, marginTop: '4px', minHeight: '16px', transition: 'all 0.3s' }}>
        {milestoneMsg ? milestoneMsg : (currentStreak === 0 ? 'Submit a task to start!' : 'Keep it up!')}
      </div>
    </div>
  );
}

